CREATE TABLE IF NOT EXISTS users (id text PRIMARY KEY, mobile text UNIQUE NOT NULL, username text UNIQUE NOT NULL, password_hash text NOT NULL, coins bigint NOT NULL DEFAULT 0, diamonds bigint NOT NULL DEFAULT 0, followers bigint NOT NULL DEFAULT 0, following bigint NOT NULL DEFAULT 0, likes bigint NOT NULL DEFAULT 0, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS rooms (id text PRIMARY KEY, host_id text NOT NULL, host_name text NOT NULL, title text NOT NULL, category text NOT NULL, status text NOT NULL, viewer_count bigint NOT NULL DEFAULT 0, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS messages (id text PRIMARY KEY, room_id text NOT NULL, user_id text NOT NULL, username text NOT NULL, text text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS transactions (id text PRIMARY KEY, user_id text NOT NULL, type text NOT NULL, amount bigint NOT NULL, room_id text, receiver_id text, sender_id text, description text, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS follows (from_user text NOT NULL, to_user text NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(from_user,to_user));
CREATE TABLE IF NOT EXISTS reports (id text PRIMARY KEY, reporter_id text NOT NULL, target_user_id text, room_id text, message_id text, reason text NOT NULL, status text NOT NULL DEFAULT 'open', created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS blocks (from_user text NOT NULL, to_user text NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(from_user,to_user));
